DROP TABLE IF EXISTS `evaluation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `evaluation` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '测评ID',
  `student_id` bigint NOT NULL COMMENT '关联student.id',
  `study_subject` smallint NOT NULL DEFAULT '1',
  `total_score` int DEFAULT '0' COMMENT '总分',
  `sign_score` int DEFAULT NULL COMMENT '交通标志得分',
  `law_score` int DEFAULT NULL COMMENT '交通法规得分',
  `safe_score` int DEFAULT NULL COMMENT '安全常识得分',
  `drive_score` int DEFAULT NULL COMMENT '驾驶理论得分',
  `level` varchar(16) DEFAULT NULL COMMENT '能力等级',
  `weak_know` text COMMENT '薄弱知识点(JSON)',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '测评时间',
  `simple_rate` int DEFAULT '0' COMMENT '简单题全局正确率(%)',
  `mid_rate` int DEFAULT '0' COMMENT '中等题全局正确率(%)',
  `diff_detail` text COMMENT '难度分层详情(JSON)',
  PRIMARY KEY (`id`),
  KEY `idx_student` (`student_id`)
) ENGINE=InnoDB AUTO_INCREMENT=50 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='能力测评表';
