DROP TABLE IF EXISTS `student`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '学员ID',
  `email` varchar(64) NOT NULL COMMENT '登录邮箱',
  `password` varchar(64) NOT NULL COMMENT '密码(bcrypt加密)',
  `name` varchar(32) DEFAULT NULL COMMENT '姓名',
  `coach_id` bigint DEFAULT NULL COMMENT '专属教练ID',
  `train_type` tinyint NOT NULL DEFAULT '1' COMMENT '培训类型: 1驾考/2客运/3货运/4危险品',
  `car_type` varchar(8) DEFAULT NULL COMMENT '报考车型: C1/C2/A1/A2',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态: 1正常/2结业/3弃学/4禁用',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `study_subject` smallint DEFAULT '1' COMMENT '学习方向: 1科目一/4科目四/3专业人员',
  `evaluation_status` tinyint DEFAULT '0' COMMENT '测评状态: 0未测评/1已完成',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_email` (`email`),
  KEY `idx_coach_id` (`coach_id`),
  CONSTRAINT `fk_student_coach` FOREIGN KEY (`coach_id`) REFERENCES `coach` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='学员表';
