INSERT INTO `subject1_question` VALUES (1,1,'判断题','驾驶机动车在道路上违反道路通行规定应当接受相应的处罚。','','','','','√',NULL,1,'2026-06-27 09:08:03','2026-06-27 16:48:12','交通法规'),(2,2,'单选题','机动车驾驶人违法驾驶造成重大交通事故构成犯罪的，依法追究什么责任？','刑事责任','民事责任','经济责任','直接责任','A',NULL,1,'2026-06-27 09:08:03','2026-06-27 16:48:12','交通法规'),(3,3,'单选题','驾驶机动车在道路上违反道路交通安全法的行为，属于什么行为？','违章行为','违法行为','过失行为','违规行为','B',NULL,1,'2026-06-27 09:08:03','2026-06-27 16:48:12','交通法规'),(4,4,'判断题','驾驶机动车违反道路交通安全法律法规发生交通事故属于交通违章行为。',NULL,NULL,NULL,NULL,'×',NULL,1,'2026-06-27 09:08:03','2026-06-27 16:48:12','交通法规'),(5,5,'判断题','对未取得驾驶证驾驶机动车的，追究其法律责任。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:08:03','2026-06-27 16:48:12','交通法规'),(6,6,'判断题','对违法驾驶发生重大交通事故且构成犯罪的，不追究其刑事责任。',NULL,NULL,NULL,NULL,'×',NULL,2,'2026-06-27 09:08:03','2026-06-27 16:48:12','交通法规'),(7,7,'判断题','驾驶机动车在道路上违反交通安全法规的行为属于违法行为。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:08:03','2026-06-27 16:48:12','交通法规'),(8,8,'判断题','伪造、变造机动车驾驶证构成犯罪的将被依法追究刑事责任。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:08:03','2026-06-27 16:48:12','交通法规'),(9,9,'单选题','驾驶这种机动车上路行驶属于什么行为？','违规行为','违章行为','违法行为','犯罪行为','C','1_9.png',1,'2026-06-27 09:08:03','2026-06-27 16:48:12','交通法规'),(10,10,'单选题','驾驶机动车跨越双实线行驶属于什么行为？','违章行为','违法行为','过失行为','违规行为','B',NULL,1,'2026-06-27 09:08:03','2026-06-27 16:48:12','交通法规'),(11,11,'判断题','驾驶机动车在人行横道上临时停车属于违法行为。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:08:03','2026-06-27 16:48:12','交通法规'),(12,12,'单选题','驾驶机动车发生交通事故后当事人故意破坏、伪造现场、毁灭证据的，应当承担什么责任？','主要责任','次要责任','同等责任','全部责任','D',NULL,2,'2026-06-27 09:08:03','2026-06-27 16:48:12','交通法规'),(13,13,'单选题','非机动车驾驶人、行人故意碰撞机动车造成交通事故的，机动车一方不承担赔偿责任。','正确','错误',NULL,NULL,'A',NULL,2,'2026-06-27 09:08:03','2026-06-27 16:48:12','交通法规'),(14,14,'单选题','以下哪项行为可构成危险驾驶罪？','闯红灯','无证驾驶','疲劳驾驶','醉驾','D',NULL,2,'2026-06-27 09:08:03','2026-06-27 16:48:12','交通法规'),(15,15,'单选题','驾驶机动车发生交通事故，仅造成财产损失的， 但是对交通事故事实及成因有争议的，','迅速报警','占道继续和对方争辩','找中间人帮忙解决','自行协商损害赔偿事宜','A',NULL,2,'2026-06-27 09:08:03','2026-06-27 16:48:12','交通法规'),(16,16,'单选题','机动车所有人申请转移登记前， 应当将涉及该车的道路交通安全违法行为和交通事故处理完毕。','正确','错误',NULL,NULL,'A',NULL,2,'2026-06-27 09:08:03','2026-06-27 16:48:12','交通法规'),(17,17,'单选题','驾驶机动车与行人之间发生交通事故造成人身伤亡、财产损失的， 机动车—方没有过错的，不承担赔偿责任。','正确','错误',NULL,NULL,'B',NULL,2,'2026-06-27 09:08:03','2026-06-27 16:48:12','交通法规'),(18,18,'单选题','请判断—下图中左侧机动车有几种违法行为？','两种违法行为','三种违法行为','四种违法行为','五种违法行为','B','1_18.png',2,'2026-06-27 09:08:03','2026-06-27 16:48:12','交通法规'),(19,19,'单选题','请判断—下图中红色机动车有几种违法行为？','一种违法行为','两种违法行为','三种违法行为','四种违法行为','C','1_19.png',2,'2026-06-27 09:08:03','2026-06-27 16:48:12','交通法规'),(20,20,'单选题','请判断图中这辆逆向行驶的灰色汽车属于什么行为？','违法行为','违规行为','违章行为','违纪行为','A','1_20.png',1,'2026-06-27 09:08:03','2026-06-27 16:48:12','交通法规'),(21,21,'判断题','驾驶人要按照驾驶证载明的准驾车型驾驶车辆。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:08:03','2026-06-27 16:48:12','驾驶理论'),(22,22,'单选题','准驾车型为小型汽车的，可以驾驶下列哪种车辆？','低速载货汽车','中型客车','三轮摩托车','轮式自行机械','A',NULL,2,'2026-06-27 09:08:03','2026-06-27 16:48:12','驾驶理论'),(23,23,'单选题','准驾车型为小型自动挡汽车的，可以驾驶以下哪种车型？','低速载货汽车','小型汽车','二轮摩托车','轻型自动挡载货汽车','D',NULL,2,'2026-06-27 09:08:03','2026-06-27 16:48:12','驾驶理论'),(24,24,'判断题','准驾车型为小型汽车的，可以驾驶小型自动挡载客汽车。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:08:03','2026-06-27 16:48:12','驾驶理论'),(25,25,'判断题','准驾车型为小型自动挡汽车的，可以驾驶低速载货汽车。',NULL,NULL,NULL,NULL,'×',NULL,2,'2026-06-27 09:08:03','2026-06-27 16:48:12','驾驶理论'),(26,26,'单选题','初次申领机动车驾驶证的，可以申请下列哪种准驾车型？','中型客车','大型客车','普通三轮摩托车','牵引车','C',NULL,2,'2026-06-27 09:08:03','2026-06-27 16:48:12','驾驶理论'),(27,27,'单选题','准驾车型为C1驾照，还可以驾驶下列哪种车型？','C2小型自动挡汽车','C3低速载货汽车','C4三轮汽车','以上都可','D',NULL,2,'2026-06-27 09:08:03','2026-06-27 16:48:12','驾驶理论'),(28,28,'判断题','驾驶人在驾驶证丢失后3个月内还可以驾驶机动车。',NULL,NULL,NULL,NULL,'×',NULL,2,'2026-06-27 09:08:03','2026-06-27 16:48:12','驾驶理论'),(29,29,'判断题','驾驶人持超过有效期的驾驶证可以在1年内驾驶机动车。',NULL,NULL,NULL,NULL,'×',NULL,2,'2026-06-27 09:08:03','2026-06-27 16:48:12','驾驶理论'),(30,30,'判断题','驾驶人的驾驶证损毁后不得驾驶机动车。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:08:03','2026-06-27 16:48:12','驾驶理论'),(31,31,'单选题','初次申领的机动车驾驶证