,NULL,NULL,NULL,'√','1_452.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(951,453,'单选题','驾驶车辆进入高速公路加速车道后，须尽快将车速提高到每小时60公里以上的原因是什么？','以防被其他车辆超过','以防后方车辆发生追尾事故','以防汇入车流时影响主线车道上行驶的车辆','以防违反最低限速要求受到处罚','C',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(952,454,'单选题','高速公路上同时有最高和最低速度限制，因为过快或者过慢都容易导致追尾。',NULL,NULL,NULL,NULL,'A',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(953,455,'单选题','在这条车道行驶的最低车速是120公里。','正确','错误',NULL,NULL,'B','1_455.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(954,456,'单选题','驾驶小型载客汽车在高速公路上时速超过100公里时的跟车距离是多少？','保持50米以上','保持60米以上','保持80米以上','保持100米以上','D',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(955,457,'单选题','驾驶小型载客汽车在高速公路上时速低于100公里时的最小跟车距离是多少？','不得少于50米','不得少于30米','不得少于20米','不得少于10米','A',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(956,458,'单选题','驾驶机动车在高速公路上行驶，遇低能见度气象条件时，能见度在200米以下，车速不得超过每小时多少公里，与同车道前车至少保持多少米的距离？','60，100','70,100','40,80','30，80','A',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(957,459,'单选题','雪天在高速公路上驾驶时，关于安全车距错误的说法是什么？','雪天路滑，制动距离比干燥柏油路更长','雪天能见度低，应该根据能见度控制安全距离','能见度小于200m时，与前车至少保持50M的安全距离','能见度小于50M时，应该驶离高速公路','C',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(958,460,'单选题','驾驶机动车在高速公路遇到能见度低于200米的气象条件时，最高车速不能超过60公里／小时， 与前车距离要保持100米以上。','正确','错误',NULL,NULL,'A',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(959,461,'单选题','在图中所示的高速公路行车道跟随前车行驶时，最小的跟车距离不得少于100米。','正确','错误',NULL,NULL,'A','1_461.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(960,462,'单选题','在能见度小于200米的高速公路上以60km/h速度行驶时，与同车道前车安全距离是多少？','保持在100米以上的距离','保持在100米以内的距离','保持与车速相同数据的距离','保持不小于50米的安全距离','A','1_462.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(961,463,'单选题','这辆在高速公路上临时停放的故障车，警告标志应该设置在车后多远处？','150米以外','50～150米','50～100米','50米以内','A','1_463.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(962,464,'单选题','机动车在高速公路上发生故障时错误的做法是什么？','开启危险报警闪光灯','按规定设置警告标志','车上人员不能下车','迅速报警','C',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(963,465,'单选题','机动车在高速公路上发生故障或交通事故无法正常行驶时由什么车拖曳或牵引？','过路车','大客车','同行车','清障车','D',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(964,466,'判断题','机动车在高速公路上发生故障时，在来车方向50至100米处设置警告标志。',NULL,NULL,NULL,NULL,'×',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(965,467,'判断题','机动车在高速公路上发生故障时，将车上人员迅速转移到右侧路肩上或者应急车道内，并且迅速报警。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(966,468,'判断题','机动车在高速公路上发生交通事故无法正常行驶时，用救援车、清障车拖曳、牵引。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(967,469,'单选题','下列做法是否正确？',NULL,NULL,NULL,NULL,'B','1_469.png',1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(968,470,'单选题','高速公路上车辆发生故障后，开启危险报警闪光灯和摆放警告标志的作用是警告后续车辆注意避让。',NULL,NULL,NULL,NULL,'A',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(969,471,'单选题','车辆发生故障无法移动时，以下做法是否正确？','正确','错误',NULL,NULL,'B','1_471.png',1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(970,472,'单选题','驾驶机动车在高速公路上发生故障，需要停车排除故障时，若能将机动车移至应急车道内，则不需要开启危险报警闪光灯。','正确','错误',NULL,NULL,'B',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(971,473,'单选题','车辆发生故障而无法移动时，首先应在车辆后方50-150米处放置危险警告标志，防止后车追尾。','正确','错误',NULL,NULL,'B',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(972,474,'单选题','高速公路上车辆发生故障后，开启危险报警闪光灯和摆放警告标志是为了向其他车辆求助。','正确','错误',NULL,NULL,'B',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(973,475,'单选题','在高速公路行驶，遇到图中所示的车辆无法继续行驶，应怎样放置危险警告标志？','在车后50米处放置警告标志','在车后50米至100米处放置警告标志','在车后150米以外放置警告标志','根据道路交通情况在适当位置放置警告标志','C','1_475.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(974,476,'判断题','驾驶机动车通过漫水路时要加速行驶。',NULL,NULL,NULL,NULL,'×',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(975,477,'判断题','驾驶机动车遇到漫水桥时要察明水情确认安全后再低速通过。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(976,478,'单选题','行至漫水路段时，应当怎样做？','低速通过涉水路段','高档位低速通过','高速通过，减少涉水时间','空挡滑行','A',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(977,479,'单选题','在涉水路段跟车时，应当怎样做?','紧跟其后','并行通过','适当增加车距','超越前车，抢先通过','C',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(978,480,'判断题','驾驶机动车行径漫水路或者漫水桥时，应当停车察明水情确认安全后再低速通过。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(979,481,'单选题','如图所示，驾驶机动车遇到这种情况时，以下做法正确的是什么？','应停车察明水情，确认安全后，低速通过','应停车察明水情，确认安全后，快速通过','应减速观察水情，然后加速行驶通过','可随意通行','A','1_481.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(980,482,'单选题','如图所示，驾驶机动车遇到这种情况时，以下做法正确的是什么？','应减速观察水情，然后加速行驶通过','应停车察明水情，确认安全后，低速通过','应停车察明水情，确认安全后，快速通过','可随意通行','B','1_482.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(981,483,'单选题','驾驶机动车行经漫水路或者漫水桥时，应当停车察明水情，快速通过。','正确','错误',NULL,NULL,'B',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(982,484,'单选题','跟车进入漫水路段时，怎么样是正确的？','如果跟车距离太近，可停车等待','增加与前车的距离，谨慎踉车慢行','紧跟前车，沿前车留下的痕迹行驶','如果前车车速太慢，可适当鸣喇叭示意','B','1_484.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(983,485,'单选题','下面关于下坡熄火滑行的说法错误的是？','对于采用真空助力刹车系统的车辆而言，下坡时的熄火会使刹车系统失效','对于采用了助力转向系统的车辆而言，下坡时熄火会使转向盘变重，难以控制','下坡道熄火时，车辆不能使用发动机制动','下坡滑行是利用坡道的位能推动汽车前进，发动机不工作，可以节油，应大力提倡','D',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(984,486,'单选题','如图所示，驾驶机动车行驶至桥梁涵洞时，以下做法正确的是什么？','加速，在对向车到达前通过','减速靠右通过','保持原速继续正常行驶','鸣喇叭后加速通过','B','1_486.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(985,487,'单选题','驾驶机动车在隧道内行驶时，可以临时停车。','正确','错误',NULL,NULL,'B',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(986,488,'判断题','在这种情况下可以加速通过人行横道。',NULL,NULL,NULL,NULL,'×','1_488.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(987,489,'单选题','遇到这种情形时，应怎么办？','从行人前方绕行','停车让行人先行','鸣喇叭提醒行人','从行人后方绕行','B','1_489.png',1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(988,490,'判断题','行经这种交通标线的路段要加速行驶。',NULL,NULL,NULL,NULL,'×','1_490.png',1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(989,491,'判断题','如图所示，机动车遇行人正在通过人行横道时，要停车让行，是因为行人享有优先通行权。',NULL,NULL,NULL,NULL,'√','1_491.png',1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(990,492,'判断题','如图所示，驾驶机动车遇到这种情况能够加速通过，是因为人行横道没有行人通过。',NULL,NULL,NULL,NULL,'×','1_492.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(991,493,'单选题','遇到这种情形怎样行驶？','停车让对方车辆通过','开启左转向灯向左行驶','加速超越障碍后会车','开前照灯告知对方让行','A','1_493.png',1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(992,494,'单选题','遇有这种排队等候的情形怎么做？','依次排队等候','从右侧借道超越','从左侧跨越实线超越','从两侧随意超越','A','1_494.png',1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(993,495,'单选题','遇到前方车辆缓慢行驶时怎样行驶？','从两侧随意超越','从右侧借道超越','占对向车道超越','依次排队行驶','D','1_495.png',1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(994,496,'单选题','在路口遇到这种情形时怎样做？','停在网状线区域内等待','停在路口以外等待','跟随前车通过路口','停在路口内等待','B','1_496.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(995,497,'单选题','驾驶机动车在车道减少的路口，遇到前方车辆依次停车或缓慢行驶时怎么办？','从前车右侧路肩进入路口','从有空隙一侧进入路口','每车道一辆依次交替驶入路口','向左变道穿插进入路口','C',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(996,498,'单选题','驾驶机动车遇到前方车辆停车排队等候或缓慢行驶时怎么办？','可借道超车','占用对面车道','穿插等候的车辆','依次行驶','D',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(997,499,'单选题','驾驶机动车遇有前方交叉路口交通阻塞时怎么办？','依次停在路口外等候','可借对向车道通过','从前车两侧穿插通过','进入路口内等候','A',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(998,500,'判断题','驾驶机动车在没有交通信号的路口遇到前方车辆缓慢行驶时要依次交替通行。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(999,501,'判断题','遇到这种情况时，要加速从红车前变更车道。',NULL,NULL,NULL,NULL,'×','1_501.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(1000,502,'判断题','在交叉路口遇到这种情况时，要在红灯亮以前加速通过路口。',NULL,NULL,NULL,NULL,'×','1_502.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(1001,503,'判断题','如图所示，在这种情形下，对方车辆具有先行权.',NULL,NULL,NULL,NULL,'√','1_503.png',1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(1002,504,'判断题','遇前方路段车道减少，车辆行驶缓慢，为保证道路通畅，应借对向车道迅速通过。',NULL,NULL,NULL,NULL,'×',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(1003,505,'单选题','如图所示，驾驶机动车行驶至车道减少的路段时，遇前方机动车排队等候或行驶缓慢时，以下做法正确的是什么？','右侧车让左侧车先行','每车道一辆依次交替驶入左侧车道','左侧车让右侧车先行','右侧车寻找空隙提前进入左侧车道','B','1_505.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(1004,506,'单选题','驾驶机动车遇到前方道路拥堵时，可以借用无人通行的非机动车道行驶。','正确','错误',NULL,NULL,'B',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(1005,507,'单选题','遇前方路段车道减少行驶缓慢，为了有序、安全，应依次交替通行。','正确','错误',NULL,NULL,'A',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(1006,508,'单选题','遇到图中所示前方车辆停车等待的情形，我方车应如何行驶？','穿插到蓝色小型客车前停车','依次在蓝色小型客车后停车等待','向前直行至不能继续行驶为止','鸣喇叭催促蓝色小型客车前移','B','1_508.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通标志'),(1007,509,'单选题','在这种情形中前车怎样行驶？','正常行驶','及时让行','开启危险报警闪光灯行驶','不得变更车道','B','1_509.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通标志'),(1008,510,'判断题','行车中遇到执行紧急任务的消防车、救护车、工程救险车时要及时让行。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1009,511,'判断题','行车中遇到正在进行作业的道路养护车辆、工程作业车时要注意避让。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(1010,512,'单选题','如图所示，当A车后方有执行任务的救护车驶来时，以下做法正确的是什么?','立即停车让路','向左转弯让路','靠右减速让路','不必理会，继续行驶','C','1_512.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1011,513,'单选题','怎样通过这样的路口？','不减速通过','加速尽快通过','空挡滑行通过','减速或停车观察','D','1_513.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(1012,514,'单选题','驾驶机动车通过没有交通信号和管理人员的铁路道口怎样通过？','适当减速通过','空挡滑行通过','停车确认安全后通过','加速尽快通过','C',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(1013,515,'判断题','在这种情况的铁路道口要加速通过。',NULL,NULL,NULL,NULL,'×','1_515.png',1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(1014,516,'判断题','行至这种情况的铁路道口要停车观察。',NULL,NULL,NULL,NULL,'√','1_516.png',1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(1015,517,'单选题','如图所示，铁路道口禁止掉头的原因是什么?','有铁路道口标志','有铁路道口信号灯','铁路道口车流量大','容易引发事故','D','1_517.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通标志'),(1016,518,'判断题','如图所示，铁路道口设置这个标志，是提示驾驶人前方路口有单股铁道。',NULL,NULL,NULL,NULL,'×','1_518.png',1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通标志'),(1017,519,'单选题','遇到图中所示信号灯亮着，但栏杆还没落下，应怎样行驶？','只要栏杆还没落下就继续行驶','如果没有看到列车驶来，可以加速横过道口','在道口的停止线以外停车等待','如果已过道口停止线，就可以急速通过','C','1_519.png',1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通标志'),(1018,520,'单选题','在高速公路上开车遇到图中所示的情况时，以下操作不正确的是什么？','应该打开雾灯、近光灯、示廓灯、前后位灯，危险报警闪光灯','能见度低，应该与同车道前车间距保持—定距离','降低车速，防止紧急情况下无法及时制动','继续维持高速行驶，防止后面车辆堵塞','D','1_520.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(1019,521,'单选题','雾天行车可多鸣喇叭催促前车提速，避免发生追尾。','正确','错误',NULL,NULL,'B',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(1020,522,'单选题','遇到图中所示的情景，怎么做是正确的？','借左侧车道超越校车','变换远近光灯催促校车离开','停在校车后面等待','鸣喇叭催促校车离开','C','1_522.png',1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(1021,523,'单选题','遇到图中所示的情景，怎么做是正确的？','提前变更到中间车道超越','提前变更到最左侧车道超越','停在校车后方使用灯光催促','适当鸣喇叭低速从左侧超越','B','1_523.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(1022,524,'单选题','如图所示，夜间驾驶机动车遇对方使用远光灯，无法看清前方路况时，以下做法正确的是什么？','保持行驶方向和车速不变','自己也打开远光灯行驶','降低车速，谨慎会车','加速通过，尽快摆脱眩目光线','C','1_524.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(1023,525,'单选题','夜间驾驶机动车在没有中心隔离设施或者没有中心线的道路上行驶，以下哪种情况下应当改用近光灯？','接近没有交通信号灯控制的交叉路口时','与对向机动车会车时','接近人行横道时','城市道路照明条件不良时','B',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(1024,526,'单选题','如图所示， 夜间驾驶机动车与同方向行驶的前车距离较近时，以下做法正确的是什么？','使用远光灯，有利于观察路面情况','禁止使用远光灯，避免灯光照射至前车后视镜造成前车驾驶人眩目','使用远光灯，有利于告知前方驾驶人后方有来车','禁止使用远光灯，避免灯光照射至前车后视镜造成自己眩目','B','1_526.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(1025,527,'单选题','这位驾驶人违反法律规定的行为是什么？','没按规定握转向盘','座椅角度不对','没系安全带','驾驶姿势不正确','C','1_527.png',1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1026,528,'判断题','驾驶机动车在上道路行驶前驾驶人要按规定系好安全带。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1027,529,'判断题','机动车上路行驶时，前排乘车人可不系安全带。',NULL,NULL,NULL,NULL,'×',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1028,530,'判断题','机动车行驶中，车上少年儿童可不使用安全带。',NULL,NULL,NULL,NULL,'×',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1029,531,'单选题','驾驶人连续驾驶不得超过多长时间？','4小时','6小时','8小时','10小时','A',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1030,532,'单选题','驾驶人连续驾驶4小时以上，停车休息的时间不得少于多少？','5分钟','10分钟','15分钟','20分钟','D',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1031,533,'单选题','在什么情况下不得行车？','车窗没关闭','车门没关闭','音响没关闭','顶窗没关闭','B',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1032,534,'单选题','驾驶机动车下陡坡时不得有哪些危险行为？','提前减挡','空挡滑行','低挡行驶','制动减速','B',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1033,535,'判断题','在这段道路上一定要减少鸣喇叭的频率。',NULL,NULL,NULL,NULL,'×','1_535.png',1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1034,536,'判断题','在车门、车厢没有关好时不要驾驶机动车起步。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1035,537,'判断题','不要在驾驶室的前后窗范围内悬挂和放置妨碍驾驶人视线的物品。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1036,538,'判断题','行车中在道路情况良好的条件下可以观看车载视频。',NULL,NULL,NULL,NULL,'×',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1037,539,'判断题','驾驶小型汽车下陡坡时允许熄火滑行。',NULL,NULL,NULL,NULL,'×',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1038,540,'判断题','驾驶机动车时可以向道路上抛撒物品。',NULL,NULL,NULL,NULL,'×',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1039,541,'单选题','在道路上发生未造成人员伤亡且无争议的轻微交通事故如何处置？','疏导其他车辆绕行','保护好现场再协商','撤离现场自行协商','不要移动车辆','C',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1040,542,'判断题','驾驶机动车在道路上发生交通事故要立即将车移到路边。',NULL,NULL,NULL,NULL,'×',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1041,543,'判断题','驾驶人在发生交通事故后因抢救伤员变动现场时要标明位置。',NULL,NULL,NULL,NULL,'√',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1042,544,'判断题','在道路上发生交通事故造成人身伤亡时，要立即抢救受伤人员并迅速报警。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1043,545,'判断题','驾驶机动车碰撞建筑物、公共设施后可即行撤离现场。',NULL,NULL,NULL,NULL,'×',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1044,546,'判断题','发生交通事故造成人员受伤时，要保护现场并立即报警。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1045,547,'判断题','道路交通事故中，驾驶人有饮酒、醉酒嫌疑时，要保护现场并立即报警。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1046,548,'判断题','道路交通事故中，机动车无号牌、检验合格标志、保险标志时，要保护现场并立即报警。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1047,549,'判断题','驾驶机动车发生财产损失交通事故，当事人对事实及成因无争议的可先撤离现场。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1048,550,'判断题','驾驶机动车发生财产损失交通事故后，当事人对事实及成因无争议移动车辆时需要对现场拍照或者标划停车位置。',NULL,NULL,NULL,NULL,'√',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1049,551,'判断题','机动车发生财产损失交通事故，对应当自行撤离现场而未撤离的，交通警察不可以责令当事人撤离现场。',NULL,NULL,NULL,NULL,'×',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1050,552,'判断题','机动车发生财产损失交通事故，对应当自行撤离现场而未撤离造成交通堵塞的，可以对驾驶人处以200元罚款。',NULL,NULL,NULL,NULL,'√',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1051,553,'单选题','驾驶机动车发生交通事故未造成人身伤亡的，责任明确双方无争议时，应当如何处置？','保护好现场再协商','不要移动车辆','疏导其他车辆绕行','撤离现场自行协商','D',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1052,554,'单选题','驾驶机动车在道路上发生交通事故，任何情况下都应标明现场位置后，先行撤离现场。','正确','错误',NULL,NULL,'B',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1053,555,'判断题','驾驶机动车在高速公路要按照限速标志标明的车速行驶。',NULL,NULL,NULL,NULL,'√',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1054,556,'单选题','驾驶机动车在道路上发生交通事故，当事人不能自行移动车辆的，应当保护现场并立即报警。','正确','错误',NULL,NULL,'A',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1055,557,'单选题','驾驶机动车发生以下交通事故，哪种情况适用自行协商解决？','对方饮酒的','对事实及成因有争议的','未造成人身伤亡，对事实及成因无争议的','造成人身伤亡的','C',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1056,558,'单选题','机动车发生轻微财产损失的交通事故，对应当自行撤离现场而未撤离的，交通警察有权责令当事人撤离现场。','正确','错误',NULL,NULL,'A',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1057,559,'单选题','发生交通事故时，下列哪种情况下当事人应当保护现场并立即报警？','未造成人员伤亡的','未发生财产损失事故','未损害公共设施及建筑物的','驾驶人有酒后驾驶嫌疑的','D',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1058,560,'单选题','发生无人员伤亡的、财产轻微损失的交通事故后，以下做法正确的是什么？','必须报警，等候警察处理','开车离开现场','确保安全的情况下，对现场拍照，然后将车辆移至路边等不妨碍交通的地点','停在现场保持不动','C',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1059,561,'单选题','驾驶机动车在道路上发生交通事故造成人身伤亡的，驾驶人必须报警。','正确','错误',NULL,NULL,'A',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1061,562,'单选题','遇到这种单方交通事故，应如何处理？',NULL,NULL,NULL,NULL,'B','1_563.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1062,563,'单选题','.机动车之间发生交通事故，不管是否有人员伤亡，只要双方当事人同意，都可自行协商解决。','正确','错误',NULL,NULL,'B',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1063,564,'单选题','事故报警时，要向交警提供事故地点、人物伤情、车辆号牌等信息，协助交警快速定位到达现场。','正确','错误',NULL,NULL,'A',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1064,565,'单选题','车辆在高速公路发生故障不能移动时，驾驶人这种尝试排除故障的做法是否正确？','正确','错误',NULL,NULL,'B','1_566.png',2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1065,566,'单选题','机动车之间发生交通事故造成轻微财产损失，当事人对事实及成因无争议时，在确保安全的原则下，对现场拍照或标划事故车辆现场位置后，可自行撤离现场处理损害赔偿事宜，主要目的是什么？','双方互有损失','找现场证人就行了，不必报警','为了及时恢复交通，避免造成交通拥堵','事故后果很小，无需赔偿','C',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1066,567,'单选题','在道路上造成人身伤亡、事故后果非常严重的交通事故，可自行撤离现场。','正确','错误',NULL,NULL,'B',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1067,568,'单选题','车辆发生轻微剐蹭事故，双方驾驶人争执不下，坚持在原地等待警察来处理，造成路面堵塞，该行为会受到罚款的处罚。','正确','错误',NULL,NULL,'A',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1068,569,'单选题','驾驶机动车与行人之间发生交通事故造成人身伤亡、财产损失的， 机动车—方没有过错的，不承担赔偿责任。','正确','错误',NULL,NULL,'B',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1069,570,'单选题','机动车发生财产损失交通事故，对应当自行撤离现场而未撤离的，交警应如何处置？','责令当事人撤离现场','处以200元罚款','扣留机动车','拘留','A',NULL,2,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1070,571,'单选题','找出这辆故障车有哪种违法行为？','没有设置警告标志','没有开启危险报警闪光灯','没有将车停到路边','没有立即排除故障','A','1_572.png',1,'2026-06-27 09:17:33','2026-06-27 16:48:12','交通法规'),(1071,572,'单选题','机动车在道路上发生故障，需要停车排除时，驾驶人应该怎么办？','就地停车排除故障','开启近光灯或雾灯','将车停到不妨碍交通的地方','将车停在道路中间','C',NULL,1,'2026-06-27 09:17:33','2026-06-27 16:48:12','安全常识'),(1072,573,'单选题','机动车在道路上发生故障，难以移动时下列做法正确的是什么？','开启危险报警闪光灯','开启车上所有灯光','禁止车上人员下车','在车前方设置警告标志','A',NULL,1,'2026-06-27 09:17:33','2026-06-27 16