UNLOCK TABLES;
DROP TABLE IF EXISTS `subject4_question`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `subject4_question` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `question_number` int NOT NULL COMMENT '题号',
  `question_type` varchar(16) NOT NULL COMMENT '题型: 判断题/单选题/多选题',
  `question_text` text NOT NULL COMMENT '题干',
  `option_a` varchar(255) DEFAULT NULL COMMENT 'A选项',
  `option_b` varchar(255) DEFAULT NULL COMMENT 'B选项',
  `option_c` varchar(255) DEFAULT NULL COMMENT 'C选项',
  `option_d` varchar(255) DEFAULT NULL COMMENT 'D选项',
  `correct_answer` varchar(16) NOT NULL COMMENT '正确答案',
  `image_file` varchar(255) DEFAULT NULL COMMENT '附图文件名',
  `difficulty` int DEFAULT '1' COMMENT '难度: 1-5',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `category` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_number` (`question_number`)
) ENGINE=InnoDB AUTO_INCREMENT=1496 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='科目四题库';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `subject4_question` WRITE;
