INSERT INTO `subject4_question` VALUES (1,1,'单选题','动画1中有几种违法行为？','一种违法行为','二种违法行为','三种违法行为','四种违法行为','B','4_1.png',2,'2026-06-27 09:35:01','2026-06-27 16:50:49','交通法规'),(2,2,'单选题','动画5中有几种违法行为？','一种违法行为','二种违法行为','三种违法行为','四种违法行为','B','4_5.png',2,'2026-06-27 09:35:01','2026-06-27 16:50:49','交通法规'),(3,3,'多选题','如图所示的大货车如上路行驶，存在什么交通违法行为？','不按规定安装后下部防护装置','不按规定安装车身反光标识','不按规定喷涂放大号','不按规定安装机动车号牌','ABCD','4_8.png',2,'2026-06-27 09:35:01','2026-06-27 16:50:49','交通法规'),(4,4,'多选题','林某驾车以110公里/小时的速度在城市道路行驶，与一辆机动车追尾后弃车逃离被群众拦下。经鉴定，事发时林某血液中的酒精浓度为135.8毫克/百毫升。林某的主要违法行为是什么？','醉酒驾驶','超速驾驶','疲劳驾驶','肇事逃逸','ABD',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','交通法规'),(5,5,'多选题','周某夜间驾驶大货车在没有路灯的城市道路上以90公里/小时的速度行驶，一直开启远光灯，在通过一窄路时，因加速抢道，导致对面驶来的一辆小客车撞上右侧护栏。周某的主要违法行为是什么？','超速行驶','不按规定会车','疲劳驾驶','不按规定使用灯光','ABD',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','交通法规'),(6,6,'判断题','变更车道前确认后方无来车时可以不开转向灯变道。',NULL,NULL,NULL,NULL,'×',NULL,1,'2026-06-27 09:35:01','2026-06-27 16:50:49','交通法规'),(7,7,'多选题','这个小型客车驾车人有哪些违法行为？','接打手持电话','无证驾驶','酒后驾驶','未系安全带','ABCD','4_12.png',2,'2026-06-27 09:35:01','2026-06-27 16:50:49','交通法规'),(8,8,'多选题','行车中驾驶人接打手机或发短信有什么危害？','影响乘车人休息','分散驾驶注意力','影响正常驾驶操作','遇紧急情况反应不及','BCD',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(9,9,'多选题','下列做法哪些可以有效避免驾驶疲劳？','连续驾驶不超过4小时','用餐不宜过饱','保持良好的睡眠','餐后适当休息后驾车','ABCD',NULL,1,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(10,10,'多选题','驾驶汽车超速行驶有哪些危害？','反应距离延长','视野变窄','加重事故后果','制动距离延长','ABCD',NULL,1,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(11,11,'单选题','某日早上6时，冉某驾驶一辆大客车出发，连续行驶至上午11时，在宣汉县境内宣南路1公里处，坠于公路一侧垂直高度8.5米的陡坎下，造成13人死亡、9人受伤。冉某的主要违法行为是什么？','超速行驶','不按交通标线行驶','客车超员','疲劳驾驶','D',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','交通法规'),(12,12,'单选题','某日13时10分，罗某驾驶一辆中型客车从高速公路0公里处出发，下午14时10分行至该高速公路125公里加200米处时，发生追尾碰撞，机动车驶出西南侧路外边坡，造成11人死亡、2人受伤。罗某的主要违法行为是什么？','超速行驶','不按交通标线行驶','客车超员','疲劳驾驶','A',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','交通法规'),(13,13,'单选题','何某驾驶一辆乘载53人的大客车（核载47人），行至宁合高速公路南京境内454公里加10