,'安全常识'),(435,435,'单选题','夜间驾驶机动车在照明条件良好的路段可以不使用灯光。','正确','错误',NULL,NULL,'B',NULL,1,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(436,436,'单选题','在这种大雨中，跟车行驶时使用近光灯的目的是？','不干扰前车视线，有利自己看清道路','提醒前方车辆让行','提醒前方车辆减速','以上说法都正确','A','4_441.png',1,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(437,437,'单选题','夜间驾驶汽车通过十字交叉路口交替使用远近光灯的目的是什么？','使其他交通参与者更容易发现自己','更容易看清路面情况','提醒其他车辆我在让行','以上说法都不对','A',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(438,438,'单选题','驾驶机动车遇到沙尘、冰雹、雾、雨、雪等低能见度条件时，应该怎样做？','开启前照灯、示廓灯和后位灯','高频率鸣喇叭使其他交通参与者知道自己的位置','同向跟车较近时，应使用远光灯','适当提高车速，尽快到达目的地，结束行车','A',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(439,439,'单选题','行车中变更车道不需要提前开启转向灯。','正确','错误',NULL,NULL,'B',NULL,1,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(440,440,'单选题','驾驶机动车进入这个路口怎样使用灯光？','开启右转向灯','开启危险报警闪光灯','不用开启转向灯','开启左转向灯','C',NULL,1,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(441,441,'单选题','驾驶机动车驶出这个环岛路口怎样使用灯光？','开启左转向灯','开启危险报警闪光灯','不用开转向灯','开启右转向灯','D',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(442,442,'单选题','机动车行经视线受阻的急弯路段时，如遇对方车辆鸣喇叭示意，也应当及时鸣喇叭进行回应。','正确','错误',NULL,NULL,'A',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(443,443,'单选题','如图所示，若车后50m范围内无其他车辆，可以不打转向灯变更车道。','正确','错误',NULL,NULL,'B','4_448.png',2,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(444,444,'单选题','如图所示，驾驶机动车在居民小区遇到这种情形要连续鸣喇叭，示意行人让路。','正确','错误',NULL,NULL,'B','4_449.png',1,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(445,445,'单选题','如图所示，驾驶机动车驶出环岛时，应先驶入最右侧车道不用开启转向灯驶离即可。','正确','错误',NULL,NULL,'B','4_450.png',2,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(446,446,'单选题','夜间驾驶车辆遇自行车对向驶来时，应怎样做？','连续变换远、近光灯','不断鸣喇叭','使用近光灯，减速或停车避让','使用远光灯','C',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(447,447,'单选题','车辆在雨天临时停车时，应开启什么灯？','前后雾灯','危险报警闪光灯','前大灯','倒车灯','B',NULL,1,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(448,448,'单选题','车辆在雪天临时停车时，应开启什么灯？','前后雾灯','倒车灯','前大灯','危险报警闪光灯','D',NULL,1,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(449,449,'单选题','车辆驶入双向行驶隧道前，应开启什么灯？','危险报警闪光灯','远光灯','雾灯','示廓灯或近光灯','D',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(450,450,'单选题','在这种气象条件下起步要注意哪些方面？','开启远光灯','开启前后雾灯','只能开启左转向灯','长时间鸣喇叭','B',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(451,451,'单选题','遇有浓雾或特大雾天能见度过低，行车困难时，应怎样做？','开启前照灯，继续行驶','开启示廓灯、雾灯，靠右行驶','开启危险报警闪光灯，继续行驶','开启危险报警闪光灯和雾灯，选择安全地点停车','D',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(452,452,'单选题','机动车倒车时遇到这种情况怎样做以保证安全？','低速缓慢倒车','主动停车避让','连续鸣喇叭示意','向右转向倒车','B','4_457.png',2,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(453,453,'单选题','发生该事故的主要原因是驾驶人倒车前没有进行安全确认。','正确','错误',NULL,NULL,'A',NULL,1,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(454,454,'单选题','在这种能见度的情况下起步要开启近光灯。','正确','错误',NULL,NULL,'A',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(455,455,'单选题','雪天行车，由于路面湿滑，车轮附着力减少，因此应当加大两车之间的安全距离。','正确','错误',NULL,NULL,'A',NULL,1,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(456,456,'单选题','雪天行车，车轮的附着力大大减少，跟车距离不是主要的，只需要保持低速行驶便可以防止事故发生。','正确','错误',NULL,NULL,'B',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(457,457,'单选题','行车中遇有前方发生交通事故，需要帮助时，应怎样做？','尽量绕道躲避','立即报警，停车观望','协助保护现场，并立即报警','加速通过，不予理睬','C',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(458,458,'单选题','事故中造成这个驾驶人致命伤害的原因是什么？','没有系安全带','离转向盘距离过近','没有握紧转向盘','安全气囊没有打开','A',NULL,1,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(459,459,'单选题','机动车在紧急制动时ABS系统会起到什么作用？','缩短制动距离','保持转向能力','减轻制动惯性','自动控制方向','B',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','驾驶理论'),(460,460,'单选题','驾驶机动车的驾驶人不需要系安全带。','正确','错误',NULL,NULL,'B',NULL,1,'2026-06-27 09:35:01','2026-06-27 16:50:49','驾驶理论'),(461,461,'单选题','安装防抱死制动装置（ABS）的机动车紧急制动时，可用力踏制动踏板。','正确','错误',NULL,NULL,'A',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','驾驶理论'),(462,462,'单选题','驾驶有ABS系统的机动车在紧急制动的同时转向可能会发生侧滑。','正确','错误',NULL,NULL,'A',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','驾驶理论'),(463,463,'单选题','安装防抱死制动装置（ABS）的机动车制动时，制动距离会大大缩短。','正确','错误',NULL,NULL,'B',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','驾驶理论'),(464,464,'单选题','怎样调整汽车座椅安全头枕的高度？','调整到头枕中心对正颈部','调整到头枕中心与颈部平齐','调整到头枕中心高出头顶','调整到头枕中心能支撑头部','D',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','驾驶理论'),(465,465,'单选题','驾驶装有ABS系统的汽车怎样采取紧急制动？','用力踏制动踏板','间歇踏制动踏板','缓慢踏制动踏板','逐渐踏下制动踏板','A',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','驾驶理论'),(466,466,'多选题','车辆发生碰撞时，关于安全带作用的说法错误的是什么？','保护颈部不受伤害','减轻驾乘人员受伤程度','减轻驾驶人疲劳','保持正确驾驶姿势','ACD',NULL,1,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(467,467,'多选题','驾驶汽车不系安全带在遇紧急制动或发生碰撞时可能会发生哪些危险？','撞击风窗玻璃','减少人员伤亡','被甩出车外','造成胸部损伤','ACD',NULL,1,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(468,468,'单选题','安全头枕要调整到与颈部平齐的高度。','正确','错误',NULL,NULL,'B',NULL,1,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(469,469,'单选题','驾驶装有安全气囊的汽车可以不系安全带。','正确','错误',NULL,NULL,'B',NULL,1,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(470,470,'单选题','设有安全带装置的车辆，应要求车内乘员系安全带。','正确','错误',NULL,NULL,'A',NULL,1,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(471,471,'单选题','行车中遇交通事故受伤者需要抢救时，应怎样做？','及时将伤者送医院抢救或拨打急救电话','尽量避开，少惹麻烦','绕过现场行驶','借故避开现场','A',NULL,1,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(472,472,'单选题','水温表是用来指示哪个部件的温度？','转向系','变速器','行驶系','发动机','D',NULL,1,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(473,473,'单选题','如图所示，起步时此灯亮起表示驻车制动(手刹)放下。','正确','错误',NULL,NULL,'B','4_478.png',1,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(474,474,'单选题','遇到这种情况要开启近光灯，靠右侧行驶。','正确','错误',NULL,NULL,'A','4_479.png',2,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(475,475,'多选题','出现下列哪些情况时，需要更换轮胎？','胎侧被扎时','轮胎上有鼓包或脱皮','前轮花纹深度低于1.6mm时','轮胎花纹间夹有石子','ABC',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(476,476,'单选题','驾驶机动车遇团雾时，以下做法正确的是什么？','提高行驶速度尽快通过','开启远光灯','缩短跟车距离，保持通行效率','开启雾灯','D',NULL,2,'2026-06-27 09:35:01','2026-06-27 16:50:49','安全常识'),(477,477,'多选题','夜间驾驶机动车准备超越右侧非机动车时，以下做法正确的是什么？','交替变换远近光灯示意','保持足够的横向安全距离','从其左侧超越','加速从右侧超越','ABC','4_482.png',2,'